package net.hivel.islandsrpg.stats;
import net.hivel.islandsrpg.IslandsRPGPlugin; import net.hivel.islandsrpg.data.PlayerData; import net.hivel.islandsrpg.util.NumberUtil; import org.bukkit.entity.Player;
public class StatsService { private final IslandsRPGPlugin plugin; public StatsService(IslandsRPGPlugin plugin){this.plugin=plugin;} public boolean spend(Player p,StatType t,int amount){PlayerData d=plugin.data().get(p); if(d.statPoints<amount)return false; d.statPoints-=amount; d.addStat(t,amount); plugin.data().save(d); return true;} public double damageBonus(PlayerData d, StatType t){return d.stat(t)*plugin.getConfig().getDouble("stats."+t.key+".damage-per-point",0);} public double defenceReduction(PlayerData d){return NumberUtil.clamp(d.stat(StatType.DEFENCE)*plugin.getConfig().getDouble("stats.defence.reduction-per-point",0.00015),0,plugin.getConfig().getDouble("stats.defence.max-reduction",0.5));} public double magicBonus(PlayerData d){return NumberUtil.clamp(d.stat(StatType.MAGIC)*plugin.getConfig().getDouble("stats.magic.power-per-point",0.0004),0,plugin.getConfig().getDouble("stats.magic.max-bonus",0.75));} public double luckDropBonus(PlayerData d){double per=plugin.getConfig().getDouble("stats.luck.relative-drop-bonus-per-100-points",0.02); return NumberUtil.clamp((d.stat(StatType.LUCK)/100.0)*per,0,plugin.getConfig().getDouble("stats.luck.max-relative-drop-bonus",0.5));} }
